```python
import logging, time, requests

log = logging.getLogger(__name__)

def get_json(url, attempts=4, timeout=5):
    for attempt in range(1, attempts + 1):
        try:
            response = requests.get(url, timeout=timeout)
            if response.status_code in (429, 502, 503, 504):
                raise requests.HTTPError(f"retryable {response.status_code}", response=response)
            response.raise_for_status()
            return response.json()
        except (requests.ConnectionError, requests.Timeout, requests.HTTPError) as exc:
            if attempt == attempts or (isinstance(exc, requests.HTTPError) and exc.response is not None and exc.response.status_code < 500 and exc.response.status_code != 429):
                log.error("giving up on %s after %s tries: %s", url, attempt, exc)
                raise
            delay = min(2 ** attempt, 30)
            log.warning("try %s failed (%s); retry in %ss", attempt, exc, delay)
            time.sleep(delay)
```
Always set timeouts, retry only idempotent calls on retryable errors, back off exponentially (add jitter), log context, and fail loudly at the end. The Launchpad's Jenkins and Kubernetes clients follow the same pattern.
